SELECT card_id, member_id, card_type, valid_from, valid_until, ended_at, CASE WHEN valid_from IS NULL THEN 'valid_from_null' WHEN valid_until IS NULL THEN 'valid_until_null' WHEN valid_from >= valid_until THEN 'valid_from_not_before_valid_until' WHEN ended_at IS NOT NULL AND ended_at <= valid_from THEN 'ended_at_not_after_valid_from' WHEN ended_at IS NOT NULL AND ended_at >= valid_until THEN 'ended_at_not_before_valid_until' ELSE 'ok' END AS issue_reason FROM {{ ref('cards') }} WHERE card_type IN ('悦享年卡', '家庭季卡') AND (valid_from IS NULL OR valid_until IS NULL OR valid_from >= valid_until OR (ended_at IS NOT NULL AND (ended_at <= valid_from OR ended_at >= valid_until)))